export const CAROUSEL=Object.freeze({x:0,z:-2.6,radius:3.25,seatRadius:2.25,platformTop:.18,seatTop:.72,seatContact:.14111661911010742,rootY:.72-.14111661911010742,maxSpeed:.40,acceleration:.16,mountDuration:5.7,dismountDuration:5.7});
const control=[[-7.7,4.5],[-8,0],[-7.1,-5.8],[-3.8,-8],[1,-8.7],[6.4,-6.6],[8,-2],[7.4,3.3],[5.7,7.4],[1.2,8.8],[-4.7,8.1]];
const ORIGINAL_SHORE=control.flatMap((b,i)=>{const a=control[(i+control.length-1)%control.length],c=control[(i+1)%control.length],d=control[(i+2)%control.length];return Array.from({length:8},(_,j)=>{const t=j/8;return[0,1].map(k=>.5*(2*b[k]+(-a[k]+c[k])*t+(2*a[k]-5*b[k]+4*c[k]-d[k])*t*t+(-a[k]+3*b[k]-3*c[k]+d[k])*t*t*t));});});
// Only the new east shore is rounded; original samples elsewhere stay byte-for-byte.
const lobe=[[8,-2],[9.2,-1],[11.5,-1],[13,.5],[13.1,4.9],[12.2,7.6],[9.5,8.8],[6.3,8.7],[3.8,8.8],[1.2,8.8]];
const lobePoints=[ORIGINAL_SHORE[47],...lobe,ORIGINAL_SHORE[73]];
const arc=lobe.flatMap((b,i)=>{if(i===lobe.length-1)return[b];const a=lobePoints[i],c=lobePoints[i+2],d=lobePoints[i+3],n=i===0||i===lobe.length-2?64:16;
 const m0=b.map((v,k)=>i===0?2*(ORIGINAL_SHORE[48][k]-ORIGINAL_SHORE[47][k]):.5*(c[k]-a[k]));
 const m1=b.map((v,k)=>i===lobe.length-2?2*(ORIGINAL_SHORE[73][k]-ORIGINAL_SHORE[72][k]):.5*(d[k]-v));
 return Array.from({length:n},(_,j)=>{const t=j/n;return b.map((v,k)=>{const value=(2*t*t*t-3*t*t+1)*v+(t*t*t-2*t*t+t)*m0[k]+(-2*t*t*t+3*t*t)*c[k]+(t*t*t-t*t)*m1[k];return k===0?Math.min(13.1,value):value;});});});
export const ISLAND_SHORE=Object.freeze([...ORIGINAL_SHORE.slice(0,49),[8,-2.5],[11.5,-2.5],...arc.slice(80,-1),...ORIGINAL_SHORE.slice(72)]);
const connectedShore=unionPolygons([ISLAND_SHORE,AMUSEMENT_AIRPORT_LAND]);
const outerShore=connectedShore.reduce((best,ring)=>Math.abs(ring.reduce((s,p,i)=>{const q=ring[(i+1)%ring.length];return s+p[0]*q[1]-p[1]*q[0];},0))>Math.abs(best.reduce((s,p,i)=>{const q=best[(i+1)%best.length];return s+p[0]*q[1]-p[1]*q[0];},0))?ring:best);
export const AMUSEMENT_CONNECTED_SHORE=Object.freeze(outerShore.map(p=>Object.freeze(p)));
export const AMUSEMENT_CONNECTED_BOUNDS=Object.freeze({minX:Math.min(...AMUSEMENT_CONNECTED_SHORE.map(p=>p[0])),maxX:Math.max(...AMUSEMENT_CONNECTED_SHORE.map(p=>p[0])),minZ:Math.min(...AMUSEMENT_CONNECTED_SHORE.map(p=>p[1])),maxZ:Math.max(...AMUSEMENT_CONNECTED_SHORE.map(p=>p[1]))});
